/**
 * Vendor the EVM contract ABIs into @yieldshield/adapter-evm.
 *
 * Reads Foundry build artifacts from the smart-contracts repo (env `YS_EVM_OUT_DIR`, default
 * sibling checkout ../smart-contracts/out) and emits `as const` TypeScript modules under
 * packages/adapter-evm/src/abis/ so viem can infer full types. Generated files are committed —
 * mirror of the SDK's vendored Codama client. Re-run after the contracts change:
 *
 *   node scripts/generate-evm-abis.mjs
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT_DIR = resolve(ROOT, process.env.YS_EVM_OUT_DIR ?? "../smart-contracts/out");
const DEST = resolve(ROOT, "packages/adapter-evm/src/abis");

const CONTRACTS = [
  { file: "SplitRiskPool.sol/SplitRiskPool.json", name: "splitRiskPool" },
  { file: "SplitRiskPoolFactory.sol/SplitRiskPoolFactory.json", name: "splitRiskPoolFactory" },
  { file: "CompositeOracle.sol/CompositeOracle.json", name: "compositeOracle" },
  { file: "ShieldReceiptNFT.sol/ShieldReceiptNFT.json", name: "shieldReceiptNft" },
  { file: "ProtectorReceiptNFT.sol/ProtectorReceiptNFT.json", name: "protectorReceiptNft" },
  { file: "ConfigurableTokenFaucet.sol/ConfigurableTokenFaucet.json", name: "tokenFaucet" },
];

mkdirSync(DEST, { recursive: true });
for (const { file, name } of CONTRACTS) {
  const artifact = JSON.parse(readFileSync(resolve(OUT_DIR, file), "utf8"));
  const body =
    `// Generated by scripts/generate-evm-abis.mjs from ${file} — do not edit by hand.\n` +
    `export const ${name}Abi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;
  writeFileSync(resolve(DEST, `${name}.ts`), body);
  console.log(`wrote abis/${name}.ts (${artifact.abi.length} entries)`);
}
